#!/usr/bin/env node
// Generated by claude-kit. UserPromptSubmit hook: warns *before* auto-compaction (#16).
// Reads the context size of the last turn from the session transcript; past 60% of the
// window (or CLAUDE_KIT_COMPACT_AT tokens, if set) it asks Claude, once, to bring .claude/context/task_context.md
// up to date, and past 80% to do it now and suggest /compact. Compaction then keeps a
// deliberate summary instead of an accidental one.
// Every 10 prompts it also asks Claude to log new decisions in the team memory file,
// if that feature is on: incremental memory without an extra model call.
// Window size: taken from the claude-kit status line when it runs, else inferred from the model;
// override with CLAUDE_KIT_CONTEXT_WINDOW=200000.
'use strict';

const fs = require('node:fs');
const os = require('node:os');
const path = require('node:path');

const WARN = 60;
const CRIT = 80;
const TASK_CONTEXT = '.claude/context/task_context.md';
/** Team memory file, or null when the memory feature is off. */
const MEMORY = '.claude/context/conversation_memory.md';
const SUMMARY_INTERVAL = 10;
const TAIL_BYTES = 512 * 1024;

function readInput() {
  try {
    return JSON.parse(fs.readFileSync(0, 'utf8'));
  } catch {
    return {};
  }
}

/** Last main-thread assistant usage, scanning only the end of the transcript. */
function lastUsage(file) {
  let fd;
  try {
    fd = fs.openSync(file, 'r');
    const size = fs.fstatSync(fd).size;
    const start = Math.max(0, size - TAIL_BYTES);
    const buf = Buffer.alloc(size - start);
    fs.readSync(fd, buf, 0, buf.length, start);
    const lines = buf.toString('utf8').split('\n');
    for (let i = lines.length - 1; i >= 0; i--) {
      const line = lines[i];
      if (!line.includes('"usage"')) continue;
      let entry;
      try {
        entry = JSON.parse(line);
      } catch {
        continue; // first line of the tail may be cut
      }
      const msg = entry.message;
      if (entry.type !== 'assistant' || entry.isSidechain || !msg || !msg.usage) continue;
      const u = msg.usage;
      const used =
        (u.input_tokens || 0) +
        (u.cache_read_input_tokens || 0) +
        (u.cache_creation_input_tokens || 0) +
        (u.output_tokens || 0);
      return { used, model: String(msg.model || '') };
    }
  } catch {
    // no transcript yet
  } finally {
    if (fd !== undefined) fs.closeSync(fd);
  }
  return null;
}

function stateFile(sessionId, kind) {
  return path.join(
    os.tmpdir(),
    `claude-kit-${kind}-${String(sessionId).replace(/[^\w-]/g, '')}.json`,
  );
}

function windowSize(sessionId, model, used) {
  const fromEnv = Number(process.env.CLAUDE_KIT_CONTEXT_WINDOW);
  if (fromEnv > 0) return fromEnv;
  try {
    const seen = JSON.parse(fs.readFileSync(stateFile(sessionId, 'window'), 'utf8')).size;
    if (seen > 0) return seen;
  } catch {
    // status line not enabled
  }
  if (
    /\[1m\]/i.test(model) ||
    /claude-(?:fable|mythos|opus|sonnet|haiku)-5/.test(model) ||
    used > 200000
  )
    return 1000000;
  return 200000;
}

function readState(file) {
  try {
    const st = JSON.parse(fs.readFileSync(file, 'utf8'));
    return { level: st.level || 0, turns: st.turns || 0 };
  } catch {
    return { level: 0, turns: 0 }; // first prompt of the session
  }
}

/** 0 = fine, 1 = update task context soon, 2 = update now and compact. */
function contextLevel(sessionId, last) {
  if (!last) return { level: 0, pct: 0 };
  const pct = Math.round((100 * last.used) / windowSize(sessionId, last.model, last.used));
  const compactAt = Number(process.env.CLAUDE_KIT_COMPACT_AT) || 0;
  const level = pct >= CRIT ? 2 : pct >= WARN || (compactAt > 0 && last.used >= compactAt) ? 1 : 0;
  return { level, pct, used: last.used };
}

function main() {
  const input = readInput();
  if (!input.transcript_path || !input.session_id) return 0;
  const file = stateFile(input.session_id, 'guard');
  const state = readState(file);
  const turns = state.turns + 1;
  const { level, pct, used } = contextLevel(input.session_id, lastUsage(input.transcript_path));
  // Context shrank (compaction): allow the same warning again later.
  const warned = Math.min(state.level, level);

  const notes = [];
  if (level > warned) {
    const where = `context is at ${pct}% of the window (~${Math.round(used / 1000)}K tokens)`;
    notes.push(
      level === 2
        ? `claude-kit: ${where}. Before anything else, update ${TASK_CONTEXT} (goal, decisions, files touched, next steps), then tell the user it's a good moment to run /compact.`
        : `claude-kit: ${where}. At the next natural pause, update ${TASK_CONTEXT} so the task state survives compaction.`,
    );
  }
  if (MEMORY && turns % SUMMARY_INTERVAL === 0)
    notes.push(
      `claude-kit: ${SUMMARY_INTERVAL} prompts since the last memory check. If a decision was made or an approach rejected since then, append one dated line each to ${MEMORY}; otherwise ignore this note.`,
    );

  try {
    fs.writeFileSync(file, JSON.stringify({ level: Math.max(warned, level), turns }));
  } catch {
    // state is best effort; worst case a warning repeats
  }
  if (notes.length)
    process.stdout.write(
      JSON.stringify({
        hookSpecificOutput: {
          hookEventName: 'UserPromptSubmit',
          additionalContext: notes.join('\n'),
        },
      }),
    );
  return 0;
}

try {
  process.exit(main());
} catch (err) {
  process.stderr.write(`claude-kit context guard: ${err && err.message}\n`);
  process.exit(0); // never block a prompt
}
